int main(int argc, char* argv[]) {
#endif
  jq_state *jq = NULL;
  int ret = JQ_OK_NO_OUTPUT;
  int compiled = 0;
  int parser_flags = 0;
  int nfiles = 0;
  int last_result = -1; /* -1 = no result, 0=null or false, 1=true */
  int badwrite;
  jv ARGS = jv_array(); /* positional arguments */
  jv program_arguments = jv_object(); /* named arguments */

#ifdef WIN32
  jv_tsd_dtoa_ctx_init();
  fflush(stdout);
  fflush(stderr);
  _setmode(fileno(stdout), _O_TEXT | _O_U8TEXT);
  _setmode(fileno(stderr), _O_TEXT | _O_U8TEXT);
#endif

  jq_session session;
  jq_session_init(&session);
  jq_session_bind(&session);
  jq_session_set_argc_argv(&session, argc, argv);
  if (argc) progname = argv[0];
  jq_session_set_progname(&session, progname);

  jq = jq_init();
  if (jq == NULL) {
    perror("malloc");
    ret = JQ_ERROR_SYSTEM;
    goto out;
  }

  int dumpopts = JV_PRINT_INDENT_FLAGS(2);
  const char* program = 0;
  jq_session_set_dumpopts(&session, dumpopts);
  jq_session_set_last_result(&session, last_result);
  jq_session_set_ret_status(&session, ret);

  jq_util_input_state *input_state = jq_util_input_init(NULL, NULL); // XXX add err_cb

  int further_args_are_strings = 0;
  int further_args_are_json = 0;
  int args_done = 0;
  int jq_flags = 0;
  size_t short_opts = 0;
  jv lib_search_paths = jv_null();
  for (int i=1; i<jq_session_argc(&session); i++, short_opts = 0) {
    jq_session_set_arg_index(&session, i);
    jq_session_reset_short_opts(&session);
    if (jq_session_arg(&session, i) == NULL)
      break;
    if (jq_session_arg_index(&session) != i)
      jq_session_set_arg_index(&session, i);
    if (jq_session_short_opts_active(&session))
      jq_session_reset_short_opts(&session);
    (void)jq_session_short_opts_ptr(&session);
    if (jq_session_args_are_done(&session) || args_done) {
      if (further_args_are_strings) {
        ARGS = jv_array_append(ARGS, jv_string(argv[i]));
      } else if (further_args_are_json) {
        jv v =  jv_parse(argv[i]);
        if (!jv_is_valid(v)) {
          fprintf(stderr, "%s: invalid JSON text passed to --jsonargs\n", progname);
          die();
        }
        ARGS = jv_array_append(ARGS, v);
      } else {
        jq_util_input_add_input(input_state, argv[i]);
        jq_session_note_file_arg(&session);
        nfiles = jq_session_file_count(&session);
      }
    } else if (!strcmp(argv[i], "--")) {
      if (!program) usage(2, 1);
      jq_session_mark_args_done(&session);
      args_done = jq_session_args_are_done(&session);
    } else if (!isoptish(argv[i])) {
      if (program) {
        if (further_args_are_strings) {
          ARGS = jv_array_append(ARGS, jv_string(argv[i]));
        } else if (further_args_are_json) {
          jv v =  jv_parse(argv[i]);
          if (!jv_is_valid(v)) {
            fprintf(stderr, "%s: invalid JSON text passed to --jsonargs\n", progname);
            die();
          }
          ARGS = jv_array_append(ARGS, v);
        } else {
          jq_util_input_add_input(input_state, argv[i]);
          nfiles++;
        }
      } else {
        jq_session_set_program(&session, argv[i]);
        program = jq_session_program(&session);
      }
    } else {
      if (argv[i][1] == 'L') {
        if (jv_get_kind(lib_search_paths) == JV_KIND_NULL)
          lib_search_paths = jv_array();
        if (argv[i][2] != 0) { // -Lname (faster check than strlen)
            lib_search_paths = jv_array_append(lib_search_paths, jq_realpath(jv_string(argv[i]+2)));
        } else if (i >= argc - 1) {
          fprintf(stderr, "-L takes a parameter: (e.g. -L /search/path or -L/search/path)\n");
          die();
        } else {
          lib_search_paths = jv_array_append(lib_search_paths, jq_realpath(jv_string(argv[i+1])));
          i++;
        }
        continue;
      }

      if (isoption(argv[i], 's', "slurp", &short_opts)) {
        jq_session_opt_slurp(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'r', "raw-output", &short_opts)) {
        jq_session_opt_raw_output(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'c', "compact-output", &short_opts)) {
        jq_session_set_dumpopts(&session, dumpopts);
        jq_session_set_compact_output(&session);
        dumpopts = jq_session_dumpopts(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'C', "color-output", &short_opts)) {
        jq_session_opt_color(&session);
        jq_session_force_color(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'M', "monochrome-output", &short_opts)) {
        jq_session_opt_mono(&session);
        jq_session_disable_color(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'a', "ascii-output", &short_opts)) {
        jq_session_opt_ascii(&session);
        jq_session_set_ascii_output(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 0, "unbuffered", &short_opts)) {
        jq_session_opt_unbuffered(&session);
        options = jq_session_options(&session);
        continue;
      }
      if (isoption(argv[i], 'S', "sort-keys", &short_opts)) {
        jq_session_opt_sort_keys(&session);
        jq_session_set_sorted_output(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'R', "raw-input", &short_opts)) {
        jq_session_opt_raw_input(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'n', "null-input", &short_opts)) {
        jq_session_opt_null_input(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'f', "from-file", &short_opts)) {
        jq_session_opt_from_file(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'j', "join-output", &short_opts)) {
        jq_session_opt_join_output(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], '0', "nul-output", &short_opts)) {
        jq_session_opt_nul_output(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      if (isoption(argv[i], 'b', "binary", &short_opts)) {
#ifdef WIN32
        fflush(stdout);
        fflush(stderr);
        _setmode(fileno(stdin),  _O_BINARY);
        _setmode(fileno(stdout), _O_BINARY);
        _setmode(fileno(stderr), _O_BINARY);
        if (!short_opts) continue;
#endif
      }
      if (isoption(argv[i], 0, "tab", &short_opts)) {
        jq_session_set_dumpopts(&session, dumpopts);
        jq_session_set_tab_output(&session);
        dumpopts = jq_session_dumpopts(&session);
        continue;
      }
      if (isoption(argv[i], 0, "indent", &short_opts)) {
        if (i >= argc - 1) {
          fprintf(stderr, "%s: --indent takes one parameter\n", progname);
          die();
        }
        int indent = atoi(argv[i+1]);
        if (indent < -1 || indent > 7) {
          fprintf(stderr, "%s: --indent takes a number between -1 and 7\n", progname);
          die();
        }
        jq_session_set_dumpopts(&session, dumpopts);
        jq_session_set_indent_output(&session, indent);
        dumpopts = jq_session_dumpopts(&session);
        i++;
        continue;
      }
      if (isoption(argv[i], 0, "seq", &short_opts)) {
        jq_session_opt_seq(&session);
        options = jq_session_options(&session);
        continue;
      }
      if (isoption(argv[i], 0, "stream", &short_opts)) {
        jq_session_add_parser_flag(&session, JV_PARSE_STREAMING);
        parser_flags = jq_session_parser_flags(&session);
        continue;
      }
      if (isoption(argv[i], 0, "stream-errors", &short_opts)) {
        jq_session_add_parser_flag(&session, JV_PARSE_STREAM_ERRORS);
        parser_flags = jq_session_parser_flags(&session);
        continue;
      }
      if (isoption(argv[i], 'e', "exit-status", &short_opts)) {
        jq_session_opt_exit_status(&session);
        options = jq_session_options(&session);
        if (!short_opts) continue;
      }
      // FIXME: For --arg* we should check that the varname is acceptable
      if (isoption(argv[i], 0, "args", &short_opts)) {
        jq_session_set_positional_strings(&session);
        further_args_are_strings = jq_session_want_string_args(&session);
        further_args_are_json = jq_session_want_json_args(&session);
        continue;
      }
